53	// 3) kernels for full matrix stored in unified memory, data copied to GPU explicitly via cudaMemcpy are indexes of non-zero elements
54	__global__ void spmv_unified(REAL* matrix_unified, const int num_rows, const int *rowNum, const int * columnNum, const REAL * x, REAL *y, int nnz)
55	{
